package com.fakeskills;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.GroundObject;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.WorldPoint;

public class BankStandingTracker
{
    /*
     * =========================
     * BANK STANDING RULES
     * =========================
     *
     * Player must:
     *
     * 1. Be completely stationary.
     *
     * 2. Be within 3 tiles of an approved
     *    banker NPC OR banking object.
     *
     * 3. Remain there for 5 game ticks.
     *
     * Award:
     *
     * +4.5 Bank Standing XP
     * every 4 qualifying game ticks.
     */

    private static final double XP_PER_AWARD = 2.0;

    private static final int BANK_RANGE = 3;

    private static final int TICKS_PER_AWARD = 5;

    private final Client client;

    private WorldPoint previousLocation;

    private int qualifyingTicks = 0;

    /*
     * =========================
     * APPROVED BANKER NPCS
     * =========================
     *
     * Stored lowercase so matching is
     * case-insensitive.
     */

    private static final Set<String> BANKER_NPCS =
            new HashSet<>(
                    Arrays.asList(
                            "banker",
                            "grand exchange clerk",
                            "'birds-eye' jack",
                            "arnold lydspor",
                            "ashuelot reis",
                            "cornelius",
                            "emerald benedict",
                            "eniola",
                            "fadli",
                            "gundai",
                            "peer the seer",
                            "standard banker",
                            "ghost banker",
                            "gnome banker",
                            "vampyre banker",
                            "tzhaar-ket banker",
                            "cave goblin banker",
                            "elf banker",
                            "dwarf banker"
                    )
            );

    /*
     * =========================
     * APPROVED BANK OBJECTS
     * =========================
     */

    private static final Set<String> BANK_OBJECTS =
            new HashSet<>(
                    Arrays.asList(
                            "bank booth",
                            "bank chest",
                            "poll booth",
                            "bank table",
                            "grand exchange booth",
                            "bank counter",
                            "bank desk",
                            "bank boat",
                            "bank chest-wreck",
                            "culinaromancer's chest",
                            "bank deposit box",
                            "bank deposit pot",
                            "deposit pool",
                            "mausoleum"
                    )
            );

    public BankStandingTracker(Client client)
    {
        this.client = client;
    }

    /*
     * Called once per GameTick.
     */
    public double update()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            reset();
            return 0.0;
        }

        Player player =
                client.getLocalPlayer();

        if (player == null)
        {
            reset();
            return 0.0;
        }

        WorldPoint currentLocation =
                player.getWorldLocation();

        /*
         * First observation.
         */
        if (previousLocation == null)
        {
            previousLocation =
                    currentLocation;

            qualifyingTicks = 0;

            return 0.0;
        }

        /*
         * =========================
         * MOVEMENT CHECK
         * =========================
         *
         * Bank Standing requires actually
         * standing still.
         *
         * Any movement resets the counter.
         */

        if (!currentLocation.equals(previousLocation))
        {
            previousLocation =
                    currentLocation;

            qualifyingTicks = 0;

            return 0.0;
        }

        previousLocation =
                currentLocation;

        /*
         * =========================
         * BANK CHECK
         * =========================
         *
         * Either condition is enough:
         *
         * approved NPC within 3 tiles
         *
         * OR
         *
         * approved object within 3 tiles
         */

        boolean nearBank =
                isNearBankerNpc(currentLocation)
                        || isNearBankObject(currentLocation);

        if (!nearBank)
        {
            qualifyingTicks = 0;

            return 0.0;
        }

        /*
         * We are:
         *
         * stationary
         * +
         * near an approved bank source.
         */

        qualifyingTicks++;

        /*
         * Award every four qualifying
         * game ticks.
         */

        if (qualifyingTicks >= TICKS_PER_AWARD)
        {
            qualifyingTicks = 0;

            return XP_PER_AWARD;
        }

        return 0.0;
    }

    /*
     * =========================
     * NPC DETECTION
     * =========================
     */

    private boolean isNearBankerNpc(
            WorldPoint playerLocation
    )
    {
        /*
         * Current RuneLite exposes NPCs
         * through the current WorldView.
         */
        for (
                NPC npc :
                client.getTopLevelWorldView().npcs()
        )
        {
            if (npc == null)
            {
                continue;
            }

            String name =
                    npc.getName();

            if (name == null)
            {
                continue;
            }

            String normalizedName =
                    name
                            .toLowerCase(
                                    Locale.ROOT
                            )
                            .trim();

            /*
             * Not one of our approved bankers.
             */
            if (
                    !BANKER_NPCS.contains(
                            normalizedName
                    )
            )
            {
                continue;
            }

            WorldPoint npcLocation =
                    npc.getWorldLocation();

            if (npcLocation == null)
            {
                continue;
            }

            /*
             * WorldPoint.distanceTo()
             * also protects us from NPCs
             * on another plane.
             */
            int distance =
                    playerLocation.distanceTo(
                            npcLocation
                    );

            if (distance <= BANK_RANGE)
            {
                return true;
            }
        }

        return false;
    }

    /*
     * =========================
     * OBJECT DETECTION
     * =========================
     */

    private boolean isNearBankObject(
            WorldPoint playerLocation
    )
    {
        Scene scene =
                client.getScene();

        if (scene == null)
        {
            return false;
        }

        Tile[][][] tiles =
                scene.getTiles();

        if (tiles == null)
        {
            return false;
        }

        int plane =
                client.getPlane();

        int baseX =
                client.getBaseX();

        int baseY =
                client.getBaseY();

        /*
         * Search a 7x7 square centered
         * on the player:
         *
         * -3 through +3 on X
         * -3 through +3 on Y
         */

        for (
                int dx = -BANK_RANGE;
                dx <= BANK_RANGE;
                dx++
        )
        {
            for (
                    int dy = -BANK_RANGE;
                    dy <= BANK_RANGE;
                    dy++
            )
            {
                int worldX =
                        playerLocation.getX()
                                + dx;

                int worldY =
                        playerLocation.getY()
                                + dy;

                int sceneX =
                        worldX - baseX;

                int sceneY =
                        worldY - baseY;

                /*
                 * Make sure coordinates
                 * are inside the scene.
                 */

                if (
                        plane < 0
                                || plane >= tiles.length
                )
                {
                    continue;
                }

                if (
                        sceneX < 0
                                || sceneX
                                >= tiles[plane].length
                )
                {
                    continue;
                }

                if (
                        sceneY < 0
                                || sceneY
                                >= tiles[plane][sceneX].length
                )
                {
                    continue;
                }

                Tile tile =
                        tiles[plane]
                                [sceneX]
                                [sceneY];

                if (tile == null)
                {
                    continue;
                }

                /*
                 * Confirm actual tile distance.
                 *
                 * RuneScape tile distance treats
                 * diagonal neighboring tiles
                 * appropriately.
                 */

                if (
                        playerLocation.distanceTo(
                                tile.getWorldLocation()
                        ) > BANK_RANGE
                )
                {
                    continue;
                }

                if (tileContainsBankObject(tile))
                {
                    return true;
                }
            }
        }

        return false;
    }

    /*
     * =========================
     * TILE OBJECT SEARCH
     * =========================
     */

    private boolean tileContainsBankObject(
            Tile tile
    )
    {
        /*
         * Wall object.
         */

        WallObject wallObject =
                tile.getWallObject();

        if (isApprovedBankObject(wallObject))
        {
            return true;
        }

        /*
         * Ground object.
         */

        GroundObject groundObject =
                tile.getGroundObject();

        if (isApprovedBankObject(groundObject))
        {
            return true;
        }

        /*
         * Game objects.
         */

        GameObject[] gameObjects =
                tile.getGameObjects();

        if (gameObjects != null)
        {
            for (
                    GameObject gameObject :
                    gameObjects
            )
            {
                if (
                        isApprovedBankObject(
                                gameObject
                        )
                )
                {
                    return true;
                }
            }
        }

        return false;
    }

    /*
     * =========================
     * OBJECT NAME CHECK
     * =========================
     */

    private boolean isApprovedBankObject(
            TileObject object
    )
    {
        if (object == null)
        {
            return false;
        }

        ObjectComposition composition =
                client.getObjectDefinition(
                        object.getId()
                );

        if (composition == null)
        {
            return false;
        }

        /*
         * Some RuneScape objects can
         * transform into another definition.
         *
         * Use the active form when possible.
         */

        if (
                composition.getImpostorIds()
                        != null
        )
        {
            try
            {
                ObjectComposition impostor =
                        composition.getImpostor();

                if (impostor != null)
                {
                    composition =
                            impostor;
                }
            }
            catch (Exception ignored)
            {
                /*
                 * Keep original definition.
                 */
            }
        }

        String name =
                composition.getName();

        if (name == null)
        {
            return false;
        }

        String normalizedName =
                name
                        .toLowerCase(
                                Locale.ROOT
                        )
                        .trim();

        return BANK_OBJECTS.contains(
                normalizedName
        );
    }

    /*
     * =========================
     * RESET
     * =========================
     */

    public void reset()
    {
        previousLocation = null;
        qualifyingTicks = 0;
    }
}

package com.fakeskills;

import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.util.Text;

public class DoublingDownTracker
{
    private static final double FIRST_PAIR_XP = 4.5;
    private static final double SECOND_PAIR_XP = 9.0;

    private final Client client;

    private final Set<NPC> trackedNpcs =
            new HashSet<>();

    /*
     * Combat still uses its own sequential pair.
     */
    private String waitingMonsterName = null;

    /*
     * General actions now have independent pending pairs.
     *
     * Example:
     *
     * examine|orange
     * chop down|willow
     * open|door
     *
     * can all be waiting simultaneously.
     */
    private final Set<String> waitingActions =
            new LinkedHashSet<>();

    private boolean doubleRewardNext = false;

    private double pendingXp = 0.0;

    public DoublingDownTracker(Client client)
    {
        this.client = client;
    }

    // =====================================================
    // COMBAT
    // =====================================================

    public void onInteractingChanged(
            InteractingChanged event
    )
    {
        if (
                client.getGameState()
                        != GameState.LOGGED_IN
        )
        {
            return;
        }

        Player localPlayer =
                client.getLocalPlayer();

        if (localPlayer == null)
        {
            return;
        }

        if (event.getSource() != localPlayer)
        {
            return;
        }

        if (!(event.getTarget() instanceof NPC))
        {
            return;
        }

        NPC npc =
                (NPC) event.getTarget();

        if (npc.getName() == null)
        {
            return;
        }

        trackedNpcs.add(npc);
    }

    public void onNpcDespawned(
            NpcDespawned event
    )
    {
        if (
                client.getGameState()
                        != GameState.LOGGED_IN
        )
        {
            return;
        }

        NPC npc =
                event.getNpc();

        if (!trackedNpcs.remove(npc))
        {
            return;
        }

        if (!npc.isDead())
        {
            return;
        }

        registerNpcKill(npc);
    }

    public double update()
    {
        if (
                client.getGameState()
                        != GameState.LOGGED_IN
        )
        {
            return collectPendingXp();
        }

        Set<NPC> deadNpcs =
                new HashSet<>();

        for (NPC npc : trackedNpcs)
        {
            if (npc == null)
            {
                continue;
            }

            if (!npc.isDead())
            {
                continue;
            }

            deadNpcs.add(npc);
            registerNpcKill(npc);
        }

        trackedNpcs.removeAll(
                deadNpcs
        );

        return collectPendingXp();
    }

    private void registerNpcKill(
            NPC npc
    )
    {
        String npcName =
                cleanText(
                        npc.getName()
                );

        if (
                npcName == null
                        || npcName.isEmpty()
        )
        {
            return;
        }

        registerKill(
                npcName
        );
    }

    private void registerKill(
            String monsterName
    )
    {
        if (waitingMonsterName == null)
        {
            waitingMonsterName =
                    monsterName;
            return;
        }

        if (
                waitingMonsterName.equals(
                        monsterName
                )
        )
        {
            awardCompletedPair();
            waitingMonsterName = null;
            return;
        }

        waitingMonsterName =
                monsterName;
    }

    // =====================================================
    // GENERAL ACTIONS
    // =====================================================

    public void onMenuOptionClicked(
            MenuOptionClicked event
    )
    {
        if (
                client.getGameState()
                        != GameState.LOGGED_IN
        )
        {
            return;
        }

        if (event == null)
        {
            return;
        }

        String option =
                cleanText(
                        event.getMenuOption()
                );

        String target =
                cleanText(
                        event.getMenuTarget()
                );

        MenuAction menuAction =
                event.getMenuAction();

        if (
                option == null
                        || option.isEmpty()
        )
        {
            return;
        }

        if (
                shouldIgnoreAction(
                        menuAction,
                        option
                )
        )
        {
            return;
        }

        /*
         * We still need a named target.
         *
         * This prevents empty interface clicks
         * from becoming meaningless pairs.
         */
        if (
                target == null
                        || target.isEmpty()
        )
        {
            return;
        }

        String actionKey =
                buildActionKey(
                        option,
                        target
                );

        registerAction(
                actionKey
        );
    }

    private String buildActionKey(
            String option,
            String target
    )
    {
        /*
         * RuneScape often presents item-on-item and
         * item-on-object interactions as "Use".
         *
         * The target text usually carries the useful
         * identity of that interaction, so preserving
         * option + target gives us a stable pair such as:
         *
         * use|knife -> logs
         *
         * or whatever exact normalized target RuneScape
         * supplies for that interaction.
         */
        return option
                + "|"
                + target;
    }

    private void registerAction(
            String actionKey
    )
    {
        /*
         * If this exact action is already armed,
         * this is occurrence #2.
         */
        if (
                waitingActions.remove(
                        actionKey
                )
        )
        {
            awardCompletedPair();
            return;
        }

        /*
         * Otherwise this exact action becomes
         * independently armed at 1/2.
         *
         * It DOES NOT erase any other pending action.
         */
        waitingActions.add(
                actionKey
        );
    }

    private boolean shouldIgnoreAction(
            MenuAction menuAction,
            String option
    )
    {
        if (menuAction == null)
        {
            return true;
        }

        /*
         * Movement itself is not an action pair.
         */
        if (menuAction == MenuAction.WALK)
        {
            return true;
        }

        if (menuAction == MenuAction.CANCEL)
        {
            return true;
        }

        /*
         * RuneLite UI/plugin actions do not count.
         */
        switch (menuAction)
        {
            case RUNELITE:
            case RUNELITE_WIDGET:
            case RUNELITE_HIGH_PRIORITY:
            case RUNELITE_LOW_PRIORITY:
            case RUNELITE_OVERLAY:
            case RUNELITE_OVERLAY_CONFIG:
            case RUNELITE_PLAYER:
            case RUNELITE_INFOBOX:
                return true;

            default:
                break;
        }

        /*
         * Combat clicks themselves do not count.
         * Confirmed NPC deaths handle combat.
         */
        if (
                option.equalsIgnoreCase(
                        "attack"
                )
        )
        {
            return true;
        }

        /*
         * EXAMINE IS INTENTIONALLY ALLOWED.
         *
         * Orange enthusiasts rejoice.
         */
        return false;
    }

    // =====================================================
    // SHARED REWARD SEQUENCE
    // =====================================================

    private void awardCompletedPair()
    {
        double reward;

        if (doubleRewardNext)
        {
            reward =
                    SECOND_PAIR_XP;
        }
        else
        {
            reward =
                    FIRST_PAIR_XP;
        }

        pendingXp += reward;

        doubleRewardNext =
                !doubleRewardNext;
    }

    private double collectPendingXp()
    {
        double xp =
                pendingXp;

        pendingXp = 0.0;

        return xp;
    }

    // =====================================================
    // TEXT CLEANUP
    // =====================================================

    private String cleanText(
            String text
    )
    {
        if (text == null)
        {
            return null;
        }

        String cleaned =
                Text.removeTags(text);

        if (cleaned == null)
        {
            return null;
        }

        return cleaned
                .replace('\u00A0', ' ')
                .trim()
                .toLowerCase(Locale.ROOT);
    }

    // =====================================================
    // TEMPORARY NPC STATE
    // =====================================================

    public void clearTemporaryNpcTracking()
    {
        trackedNpcs.clear();
        pendingXp = 0.0;
    }

    // =====================================================
    // PERSISTENT COMBAT STATE
    // =====================================================

    public String getWaitingMonsterName()
    {
        return waitingMonsterName;
    }

    public void setWaitingMonsterName(
            String monsterName
    )
    {
        if (
                monsterName == null
                        || monsterName.trim().isEmpty()
        )
        {
            waitingMonsterName = null;
            return;
        }

        waitingMonsterName =
                cleanText(
                        monsterName
                );
    }

    // =====================================================
    // PERSISTENT ACTION STATE
    // =====================================================

    /*
     * To preserve compatibility with the plugin file
     * we already built, all pending actions are stored
     * as one String separated by newline characters.
     */
    public String getWaitingAction()
    {
        if (waitingActions.isEmpty())
        {
            return null;
        }

        return String.join(
                "\n",
                waitingActions
        );
    }

    public void setWaitingAction(
            String savedActions
    )
    {
        waitingActions.clear();

        if (
                savedActions == null
                        || savedActions.trim().isEmpty()
        )
        {
            return;
        }

        String[] actions =
                savedActions.split(
                        "\\n"
                );

        for (String action : actions)
        {
            if (
                    action == null
                            || action.trim().isEmpty()
            )
            {
                continue;
            }

            waitingActions.add(
                    action.trim()
                            .toLowerCase(
                                    Locale.ROOT
                            )
            );
        }
    }

    // =====================================================
    // PERSISTENT REWARD STATE
    // =====================================================

    public boolean isDoubleRewardNext()
    {
        return doubleRewardNext;
    }

    public void setDoubleRewardNext(
            boolean doubleRewardNext
    )
    {
        this.doubleRewardNext =
                doubleRewardNext;
    }
}

package com.fakeskills;

import java.util.EnumMap;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;

public class ExpWasteTracker
{
    private static final double XP_PER_SECOND = 1.0;

    private static final long ONE_SECOND_NANOS =
            1_000_000_000L;

    /*
     * More than two still ticks are required.
     *
     * Tick 1 = no
     * Tick 2 = no
     * Tick 3 = eligible to begin idle timing.
     */
    private static final int REQUIRED_STILL_TICKS = 3;

    private final Client client;

    private final Map<Skill, Integer> previousXp =
            new EnumMap<>(Skill.class);

    private WorldPoint previousLocation = null;

    private int stillTicks = 0;

    private boolean initialized = false;

    private long idleStartTime = -1L;
    private long lastWasteAwardTime = -1L;

    private boolean gameplayActionThisTick = false;

    /*
     * If ANY of our other Fake Skills awards XP,
     * FakeSkillsPlugin tells us here.
     *
     * That means the player is not currently
     * "wasting XP".
     */
    private boolean fakeXpEarned = false;

    public ExpWasteTracker(Client client)
    {
        this.client = client;
    }

    // =====================================================
    // OTHER FAKE SKILL XP
    // =====================================================

    public void notifyFakeXpEarned()
    {
        fakeXpEarned = true;

        /*
         * Reset immediately rather than waiting
         * for the next game tick.
         */
        stillTicks = 0;
        resetIdleTimer();
    }

    // =====================================================
    // MENU ACTIONS
    // =====================================================

    public void onMenuOptionClicked(
            MenuOptionClicked event
    )
    {
        if (
                client.getGameState()
                        != GameState.LOGGED_IN
        )
        {
            return;
        }

        if (event == null)
        {
            return;
        }

        String option =
                event.getMenuOption();

        if (option == null)
        {
            return;
        }

        option =
                option.trim();

        /*
         * Examine remains glorious XP waste.
         */
        if (
                option.equalsIgnoreCase(
                        "examine"
                )
        )
        {
            return;
        }

        if (
                option.equalsIgnoreCase(
                        "cancel"
                )
        )
        {
            return;
        }

        /*
         * Actual movement is detected by tile,
         * so clicking Walk Here doesn't need
         * to count separately.
         */
        if (
                option.equalsIgnoreCase(
                        "walk here"
                )
        )
        {
            return;
        }

        gameplayActionThisTick = true;
    }

    // =====================================================
    // UPDATE
    // =====================================================

    public double update()
    {
        if (
                client.getGameState()
                        != GameState.LOGGED_IN
        )
        {
            reset();
            return 0.0;
        }

        Player player =
                client.getLocalPlayer();

        if (player == null)
        {
            reset();
            return 0.0;
        }

        long now =
                System.nanoTime();

        WorldPoint currentLocation =
                player.getWorldLocation();

        if (!initialized)
        {
            initialize(
                    currentLocation
            );

            return 0.0;
        }

        // =================================================
        // OTHER FAKE SKILL XP
        // =================================================

        if (fakeXpEarned)
        {
            fakeXpEarned = false;

            stillTicks = 0;
            resetIdleTimer();

            previousLocation =
                    currentLocation;

            gameplayActionThisTick = false;

            return 0.0;
        }

        // =================================================
        // REAL OSRS XP
        // =================================================

        boolean realXpGained =
                checkForRealXpGain();

        if (realXpGained)
        {
            stillTicks = 0;
            resetIdleTimer();

            previousLocation =
                    currentLocation;

            gameplayActionThisTick = false;

            return 0.0;
        }

        // =================================================
        // MOVEMENT
        // =================================================

        boolean moved =
                previousLocation == null
                        || !currentLocation.equals(
                        previousLocation
                );

        previousLocation =
                currentLocation;

        if (moved)
        {
            stillTicks = 0;
            resetIdleTimer();

            gameplayActionThisTick = false;

            return 0.0;
        }

        // =================================================
        // GAMEPLAY INTERACTION
        // =================================================

        if (gameplayActionThisTick)
        {
            stillTicks = 0;
            resetIdleTimer();

            gameplayActionThisTick = false;

            return 0.0;
        }

        gameplayActionThisTick = false;

        // =================================================
        // ACTIVE CHARACTER ANIMATION
        // =================================================

        if (player.getAnimation() != -1)
        {
            stillTicks = 0;
            resetIdleTimer();

            return 0.0;
        }

        // =================================================
        // ACTUALLY IDLE
        // =================================================

        stillTicks++;

        if (
                stillTicks
                        < REQUIRED_STILL_TICKS
        )
        {
            resetIdleTimer();
            return 0.0;
        }

        /*
         * We have just become truly idle.
         * Start the one-second timer.
         */
        if (idleStartTime < 0L)
        {
            idleStartTime = now;
            lastWasteAwardTime = now;

            return 0.0;
        }

        long elapsed =
                now - lastWasteAwardTime;

        long fullSeconds =
                elapsed / ONE_SECOND_NANOS;

        if (fullSeconds <= 0)
        {
            return 0.0;
        }

        lastWasteAwardTime +=
                fullSeconds
                        * ONE_SECOND_NANOS;

        return fullSeconds
                * XP_PER_SECOND;
    }

    // =====================================================
    // INITIALIZATION
    // =====================================================

    private void initialize(
            WorldPoint currentLocation
    )
    {
        previousXp.clear();

        for (Skill skill : Skill.values())
        {
            if (skill == Skill.OVERALL)
            {
                continue;
            }

            previousXp.put(
                    skill,
                    client.getSkillExperience(
                            skill
                    )
            );
        }

        previousLocation =
                currentLocation;

        stillTicks = 0;

        idleStartTime = -1L;
        lastWasteAwardTime = -1L;

        gameplayActionThisTick = false;
        fakeXpEarned = false;

        initialized = true;
    }

    // =====================================================
    // REAL XP CHECK
    // =====================================================

    private boolean checkForRealXpGain()
    {
        boolean gainedXp = false;

        for (Skill skill : Skill.values())
        {
            if (skill == Skill.OVERALL)
            {
                continue;
            }

            int currentXp =
                    client.getSkillExperience(
                            skill
                    );

            Integer oldXp =
                    previousXp.get(
                            skill
                    );

            if (
                    oldXp != null
                            && currentXp > oldXp
            )
            {
                gainedXp = true;
            }

            previousXp.put(
                    skill,
                    currentXp
            );
        }

        return gainedXp;
    }

    private void resetIdleTimer()
    {
        idleStartTime = -1L;
        lastWasteAwardTime = -1L;
    }

    // =====================================================
    // FULL RESET
    // =====================================================

    public void reset()
    {
        previousXp.clear();

        previousLocation = null;

        stillTicks = 0;

        idleStartTime = -1L;
        lastWasteAwardTime = -1L;

        gameplayActionThisTick = false;
        fakeXpEarned = false;

        initialized = false;
    }
}

package com.fakeskills;

public class FakeSkillData
{
    private static final double MAX_XP = 200_000_000.0;

    private double xp;

    public FakeSkillData()
    {
        xp = 0.0;
    }

    public double getXp()
    {
        return xp;
    }

    public void setXp(double xp)
    {
        if (xp < 0)
        {
            this.xp = 0.0;
        }
        else if (xp > MAX_XP)
        {
            this.xp = MAX_XP;
        }
        else
        {
            this.xp = xp;
        }
    }

    public void addXp(double amount)
    {
        if (amount <= 0)
        {
            return;
        }

        xp += amount;

        if (xp > MAX_XP)
        {
            xp = MAX_XP;
        }
    }

    public int getLevel()
    {
        /*
         * Fake Skills special rule:
         *
         * Normal RuneScape XP curve through Level 99.
         *
         * Level stays at 99 after 13,034,431 XP.
         *
         * At exactly 200,000,000 XP:
         * Level 120.
         */

        if (xp >= MAX_XP)
        {
            return 120;
        }

        int points = 0;
        int level = 1;

        for (int lvl = 1; lvl < 99; lvl++)
        {
            points += Math.floor(
                    lvl + 300.0 * Math.pow(2.0, lvl / 7.0)
            );

            int requiredXp =
                    (int) Math.floor(points / 4.0);

            if (xp >= requiredXp)
            {
                level = lvl + 1;
            }
            else
            {
                break;
            }
        }

        return level;
    }
}

