package com.fakeskills;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.text.DecimalFormat;

import javax.swing.ToolTipManager;

import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

public class FakeSkillsPanel extends PluginPanel
{
    // =====================================================
    // ORIGINAL ARTWORK SIZE
    // =====================================================

    private static final int ART_WIDTH = 1174;
    private static final int ART_HEIGHT = 1340;

    /*
     * RuneLite sidebar display size.
     */
    private static final int DISPLAY_WIDTH = 225;

    private static final int DISPLAY_HEIGHT =
            (int) Math.round(
                    ART_HEIGHT
                            * (DISPLAY_WIDTH / (double) ART_WIDTH)
            );

    // =====================================================
    // SIX ROW POSITIONS
    // =====================================================

    /*
     * These are our calibrated row positions.
     * Do not change these unless we deliberately
     * reposition the artwork later.
     */
    private static final int[] ROW_CENTERS =
            {
                    145,   // Bank Standing
                    355,   // Traveling
                    560,   // Yapping
                    765,   // Doubling Down
                    979,   // Praying
                    1193   // Exp Waste
            };

    // =====================================================
    // LEVEL NUMBER POSITIONS
    // =====================================================

    /*
     * Top number sits above/left of the slash.
     */
    private static final int TOP_LEVEL_RIGHT_X = 430;

    /*
     * Bottom number sits below/right of the slash.
     */
    private static final int BOTTOM_LEVEL_RIGHT_X = 500;

    private static final int TOP_NUMBER_Y_OFFSET = -27;
    private static final int BOTTOM_NUMBER_Y_OFFSET = 62;

    private static final int LEVEL_FONT_SIZE = 58;

    // =====================================================
    // XP BAR POSITIONS
    // =====================================================

    private static final int BAR_X = 570;
    private static final int BAR_WIDTH = 412;
    private static final int BAR_HEIGHT = 31;

    private static final int BAR_Y_OFFSET = 55;

    private static final int BAR_INSET_X = 8;
    private static final int BAR_INSET_Y = 7;

    /*
     * Height of the visible XP fill while keeping
     * its bottom edge aligned with the artwork.
     */
    private static final int XP_FILL_HEIGHT =
            (BAR_HEIGHT - (BAR_INSET_Y * 2)) * 2;

    private static final DecimalFormat XP_FORMAT =
            new DecimalFormat("#,##0.##");

    // =====================================================
    // ARTWORK
    // =====================================================

    private final BufferedImage background;

    // =====================================================
    // LIVE SKILL DATA
    // =====================================================

    private int bankStandingLevel = 1;
    private double bankStandingXp = 0.0;

    private int travelingLevel = 1;
    private double travelingXp = 0.0;

    private int yappingLevel = 1;
    private double yappingXp = 0.0;

    private int doublingDownLevel = 1;
    private double doublingDownXp = 0.0;

    private int prayingLevel = 1;
    private double prayingXp = 0.0;

    private int expWasteLevel = 1;
    private double expWasteXp = 0.0;

    // =====================================================
    // HOVER DESCRIPTIONS
    // =====================================================

    private int hoveredRow = -1;

    private final String[] skillDescriptions =
            {
                    "Gain exp by standing near a bank",
                    "Gain exp while traveling, 2x with a friend!",
                    "Gain exp when chatting",
                    "Gain exp by repeating actions",
                    "Gain exp by using prayers",
                    "Gain exp by doing nothing"
            };

    // =====================================================
    // CONSTRUCTOR
    // =====================================================

    public FakeSkillsPanel()
    {
        background =
                ImageUtil.loadImageResource(
                        FakeSkillsPanel.class,
                        "/fakeskills/panel_background.png"
                );

        setOpaque(false);

        /*
         * Tell Swing/RuneLite that this component
         * provides tooltip text.
         */
        ToolTipManager
                .sharedInstance()
                .registerComponent(this);

        /*
         * Watch the mouse while it moves over
         * our Fake Skills panel.
         */
        addMouseMotionListener(
                new MouseAdapter()
                {
                    @Override
                    public void mouseMoved(MouseEvent event)
                    {
                        int row =
                                getHoveredRow(
                                        event.getY()
                                );

                        if (row != hoveredRow)
                        {
                            hoveredRow = row;
                            repaint();
                        }
                    }
                }
        );

        /*
         * Clear the hovered skill when the mouse
         * leaves our interface.
         */
        addMouseListener(
                new MouseAdapter()
                {
                    @Override
                    public void mouseExited(MouseEvent event)
                    {
                        hoveredRow = -1;
                    }
                }
        );

        setPreferredSize(
                new Dimension(
                        DISPLAY_WIDTH,
                        DISPLAY_HEIGHT
                )
        );

        setMinimumSize(
                new Dimension(
                        DISPLAY_WIDTH,
                        DISPLAY_HEIGHT
                )
        );
    }

    // =====================================================
    // PAINT
    // =====================================================

    @Override
    protected void paintComponent(Graphics graphics)
    {
        super.paintComponent(graphics);

        /*
         * Build the complete interface at the
         * original artwork resolution first.
         */
        BufferedImage completedPanel =
                new BufferedImage(
                        ART_WIDTH,
                        ART_HEIGHT,
                        BufferedImage.TYPE_INT_ARGB
                );

        Graphics2D art =
                completedPanel.createGraphics();

        art.setRenderingHint(
                RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_OFF
        );

        art.setRenderingHint(
                RenderingHints.KEY_TEXT_ANTIALIASING,
                RenderingHints.VALUE_TEXT_ANTIALIAS_OFF
        );

        // Draw the static interface artwork.
        art.drawImage(
                background,
                0,
                0,
                ART_WIDTH,
                ART_HEIGHT,
                null
        );

        // Draw all six live skills.
        drawSkill(
                art,
                0,
                bankStandingLevel,
                bankStandingXp
        );

        drawSkill(
                art,
                1,
                travelingLevel,
                travelingXp
        );

        drawSkill(
                art,
                2,
                yappingLevel,
                yappingXp
        );

        drawSkill(
                art,
                3,
                doublingDownLevel,
                doublingDownXp
        );

        drawSkill(
                art,
                4,
                prayingLevel,
                prayingXp
        );

        drawSkill(
                art,
                5,
                expWasteLevel,
                expWasteXp
        );

        art.dispose();

        /*
         * Scale the entire completed interface down
         * to RuneLite sidebar size.
         */
        Graphics2D g =
                (Graphics2D) graphics.create();

        g.setRenderingHint(
                RenderingHints.KEY_INTERPOLATION,
                RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR
        );

        g.drawImage(
                completedPanel,
                0,
                0,
                DISPLAY_WIDTH,
                DISPLAY_HEIGHT,
                null
        );

        g.dispose();
    }

    // =====================================================
    // DRAW ONE SKILL
    // =====================================================

    private void drawSkill(
            Graphics2D g,
            int row,
            int level,
            double xp
    )
    {
        int centerY =
                ROW_CENTERS[row];

        drawLevelPair(
                g,
                centerY,
                level
        );

        drawXpBar(
                g,
                centerY,
                level,
                xp
        );
    }

    // =====================================================
    // LEVEL NUMBERS
    // =====================================================

    private void drawLevelPair(
            Graphics2D g,
            int centerY,
            int level
    )
    {
        String text =
                Integer.toString(level);

        g.setFont(
                new Font(
                        "Dialog",
                        Font.BOLD,
                        LEVEL_FONT_SIZE
                )
        );

        FontMetrics metrics =
                g.getFontMetrics();

        int textWidth =
                metrics.stringWidth(text);

        /*
         * Top and bottom use separate horizontal
         * positions so they surround the slash.
         */
        int topX =
                TOP_LEVEL_RIGHT_X
                        - textWidth;

        int bottomX =
                BOTTOM_LEVEL_RIGHT_X
                        - textWidth;

        int topY =
                centerY
                        + TOP_NUMBER_Y_OFFSET;

        int bottomY =
                centerY
                        + BOTTOM_NUMBER_Y_OFFSET;

        // Black shadow.
        g.setColor(
                Color.BLACK
        );

        g.drawString(
                text,
                topX + 4,
                topY + 4
        );

        g.drawString(
                text,
                bottomX + 4,
                bottomY + 4
        );

        // Yellow number.
        g.setColor(
                new Color(
                        255,
                        230,
                        0
                )
        );

        g.drawString(
                text,
                topX,
                topY
        );

        g.drawString(
                text,
                bottomX,
                bottomY
        );
    }

    // =====================================================
    // XP BAR
    // =====================================================

    private void drawXpBar(
            Graphics2D g,
            int centerY,
            int level,
            double xp
    )
    {
        double progress =
                getLevelProgress(
                        level,
                        xp
                );

        int usableWidth =
                BAR_WIDTH
                        - (BAR_INSET_X * 2);

        int fillWidth =
                (int) Math.round(
                        usableWidth
                                * progress
                );

        if (fillWidth <= 0)
        {
            return;
        }

        int x =
                BAR_X
                        + BAR_INSET_X;

        /*
         * Align the XP fill with the bottom edge
         * of the artwork's progress-bar area.
         */
        int originalHeight =
                BAR_HEIGHT
                        - (BAR_INSET_Y * 2);

        int oldBottomY =
                centerY
                        + BAR_Y_OFFSET
                        + BAR_INSET_Y
                        + originalHeight;

        int height = XP_FILL_HEIGHT;

        int y =
                oldBottomY
                        - height;

        /*
         * Dark green lower layer.
         */
        g.setColor(
                new Color(
                        75,
                        125,
                        10
                )
        );

        g.fillRect(
                x,
                y,
                fillWidth,
                height
        );

        /*
         * Bright green upper layer.
         */
        if (height > 5)
        {
            g.setColor(
                    new Color(
                            155,
                            225,
                            25
                    )
            );

            g.fillRect(
                    x,
                    y,
                    fillWidth,
                    height - 5
            );
        }
    }

    // =====================================================
    // LEVEL PROGRESS
    // =====================================================

    private double getLevelProgress(
            int level,
            double xp
    )
    {
        if (level >= 120)
        {
            return 1.0;
        }

        /*
         * Fake Skills special rule:
         *
         * Level 99 remains level 99 until 200m XP.
         * At 200m it becomes level 120.
         */
        if (level >= 99)
        {
            double startXp =
                    13_034_431.0;

            double endXp =
                    200_000_000.0;

            return clamp(
                    (xp - startXp)
                            / (endXp - startXp)
            );
        }

        double startXp =
                getXpForLevel(
                        level
                );

        double nextXp =
                getXpForLevel(
                        level + 1
                );

        double range =
                nextXp - startXp;

        if (range <= 0.0)
        {
            return 0.0;
        }

        return clamp(
                (xp - startXp)
                        / range
        );
    }

    // =====================================================
    // STANDARD OSRS XP TABLE
    // =====================================================

    private double getXpForLevel(
            int targetLevel
    )
    {
        if (targetLevel <= 1)
        {
            return 0.0;
        }

        int points = 0;

        for (
                int level = 1;
                level < targetLevel;
                level++
        )
        {
            points +=
                    Math.floor(
                            level
                                    + 300.0
                                    * Math.pow(
                                    2.0,
                                    level / 7.0
                            )
                    );
        }

        return Math.floor(
                points / 4.0
        );
    }

    private double clamp(
            double value
    )
    {
        if (value < 0.0)
        {
            return 0.0;
        }

        if (value > 1.0)
        {
            return 1.0;
        }

        return value;
    }

    // =====================================================
    // HOVER TOOLTIP
    // =====================================================

    @Override
    public String getToolTipText(MouseEvent event)
    {
        int row =
                getHoveredRow(
                        event.getY()
                );

        if (
                row < 0
                        || row >= skillDescriptions.length
        )
        {
            return null;
        }

        if (isMouseOverXpBar(event, row))
        {
            return getXpProgressTooltip(row);
        }

        return skillDescriptions[row];
    }

    private boolean isMouseOverXpBar(
            MouseEvent event,
            int row
    )
    {
        double xScale =
                ART_WIDTH
                        / (double) DISPLAY_WIDTH;

        double yScale =
                ART_HEIGHT
                        / (double) DISPLAY_HEIGHT;

        int artworkX =
                (int) Math.round(
                        event.getX() * xScale
                );

        int artworkY =
                (int) Math.round(
                        event.getY() * yScale
                );

        int originalHeight =
                BAR_HEIGHT
                        - (BAR_INSET_Y * 2);

        int barBottomY =
                ROW_CENTERS[row]
                        + BAR_Y_OFFSET
                        + BAR_INSET_Y
                        + originalHeight;

        int barTopY =
                barBottomY
                        - XP_FILL_HEIGHT;

        return artworkX >= BAR_X
                && artworkX <= BAR_X + BAR_WIDTH
                && artworkY >= barTopY
                && artworkY <= barBottomY;
    }

    private String getXpProgressTooltip(int row)
    {
        int level = getLevelForRow(row);
        double xp = getXpForRow(row);

        double targetXp;

        if (level >= 120)
        {
            targetXp = 200_000_000.0;
        }
        else if (level >= 99)
        {
            targetXp = 200_000_000.0;
        }
        else
        {
            targetXp = getXpForLevel(level + 1);
        }

        return XP_FORMAT.format(xp)
                + " / "
                + XP_FORMAT.format(targetXp)
                + " XP";
    }

    private int getLevelForRow(int row)
    {
        switch (row)
        {
            case 0:
                return bankStandingLevel;
            case 1:
                return travelingLevel;
            case 2:
                return yappingLevel;
            case 3:
                return doublingDownLevel;
            case 4:
                return prayingLevel;
            case 5:
                return expWasteLevel;
            default:
                return 1;
        }
    }

    private double getXpForRow(int row)
    {
        switch (row)
        {
            case 0:
                return bankStandingXp;
            case 1:
                return travelingXp;
            case 2:
                return yappingXp;
            case 3:
                return doublingDownXp;
            case 4:
                return prayingXp;
            case 5:
                return expWasteXp;
            default:
                return 0.0;
        }
    }

    private int getHoveredRow(int mouseY)
    {
        /*
         * Convert the mouse position into the same
         * original-artwork coordinate system used
         * by our row positions.
         */
        double scale =
                ART_HEIGHT
                        / (double) DISPLAY_HEIGHT;

        int artworkY =
                (int) Math.round(
                        mouseY * scale
                );

        /*
         * Each row occupies the space halfway
         * between its neighboring row centers.
         */
        int firstBoundary =
                (ROW_CENTERS[0] + ROW_CENTERS[1]) / 2;

        if (artworkY < firstBoundary)
        {
            return 0;
        }

        for (
                int row = 1;
                row < ROW_CENTERS.length - 1;
                row++
        )
        {
            int upperBoundary =
                    (ROW_CENTERS[row - 1]
                            + ROW_CENTERS[row]) / 2;

            int lowerBoundary =
                    (ROW_CENTERS[row]
                            + ROW_CENTERS[row + 1]) / 2;

            if (
                    artworkY >= upperBoundary
                            && artworkY < lowerBoundary
            )
            {
                return row;
            }
        }

        int lastBoundary =
                (
                        ROW_CENTERS[
                                ROW_CENTERS.length - 2
                                ]
                                + ROW_CENTERS[
                                ROW_CENTERS.length - 1
                                ]
                ) / 2;

        if (
                artworkY >= lastBoundary
                        && artworkY <= ART_HEIGHT
        )
        {
            return ROW_CENTERS.length - 1;
        }

        return -1;
    }

    // =====================================================
    // LIVE SKILL UPDATES
    // =====================================================

    public void updateBankStanding(
            int level,
            double xp
    )
    {
        bankStandingLevel = level;
        bankStandingXp = xp;
        repaint();
    }

    public void updateTraveling(
            int level,
            double xp
    )
    {
        travelingLevel = level;
        travelingXp = xp;
        repaint();
    }

    public void updateYapping(
            int level,
            double xp
    )
    {
        yappingLevel = level;
        yappingXp = xp;
        repaint();
    }

    public void updateDoublingDown(
            int level,
            double xp
    )
    {
        doublingDownLevel = level;
        doublingDownXp = xp;
        repaint();
    }

    public void updatePraying(
            int level,
            double xp
    )
    {
        prayingLevel = level;
        prayingXp = xp;
        repaint();
    }

    public void updateExpWaste(
            int level,
            double xp
    )
    {
        expWasteLevel = level;
        expWasteXp = xp;
        repaint();
    }
}

package com.fakeskills;

import com.google.inject.Provides;

import java.awt.image.BufferedImage;

import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.GameState;

import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
		name = "Fake Skills",
		description = "Adds a collection of passive fake skills to RuneLite."
)
public class FakeSkillsPlugin extends Plugin
{
	private static final String CONFIG_GROUP =
			"fakeskills";

	private static final String TRAVELING_XP_KEY =
			"travelingXp";

	private static final String BANK_STANDING_XP_KEY =
			"bankStandingXp";

	private static final String PRAYING_XP_KEY =
			"prayingXp";

	private static final String YAPPING_XP_KEY =
			"yappingXp";

	private static final String DOUBLING_DOWN_XP_KEY =
			"doublingDownXp";

	private static final String DOUBLING_DOWN_MONSTER_KEY =
			"doublingDownWaitingMonster";

	private static final String DOUBLING_DOWN_ACTION_KEY =
			"doublingDownWaitingAction";

	private static final String DOUBLING_DOWN_REWARD_KEY =
			"doublingDownDoubleRewardNext";

	private static final String EXP_WASTE_XP_KEY =
			"expWasteXp";

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private FakeSkillsConfig config;

	private FakeSkillsPanel panel;
	private NavigationButton navButton;

	private final FakeSkillData traveling =
			new FakeSkillData();

	private TravelingTracker travelingTracker;

	private final FakeSkillData bankStanding =
			new FakeSkillData();

	private BankStandingTracker bankStandingTracker;

	private final FakeSkillData praying =
			new FakeSkillData();

	private PrayingTracker prayingTracker;

	private final FakeSkillData yapping =
			new FakeSkillData();

	private YappingTracker yappingTracker;

	private final FakeSkillData doublingDown =
			new FakeSkillData();

	private DoublingDownTracker doublingDownTracker;

	private final FakeSkillData expWaste =
			new FakeSkillData();

	private ExpWasteTracker expWasteTracker;

	@Override
	protected void startUp()
	{
		travelingTracker =
				new TravelingTracker(client);

		bankStandingTracker =
				new BankStandingTracker(client);

		prayingTracker =
				new PrayingTracker(client);

		yappingTracker =
				new YappingTracker(client);

		doublingDownTracker =
				new DoublingDownTracker(client);

		expWasteTracker =
				new ExpWasteTracker(client);

		loadTravelingXp();
		loadBankStandingXp();
		loadPrayingXp();
		loadYappingXp();
		loadDoublingDownXp();
		loadExpWasteXp();

		loadDoublingDownState();

		panel =
				new FakeSkillsPanel();

		updateTravelingDisplay();
		updateBankStandingDisplay();
		updatePrayingDisplay();
		updateYappingDisplay();
		updateDoublingDownDisplay();
		updateExpWasteDisplay();

		BufferedImage icon =
				ImageUtil.loadImageResource(
						FakeSkillsPlugin.class,
						"/fakeskills/icon.png"
				);

		navButton =
				NavigationButton.builder()
						.tooltip("Fake Skills")
						.icon(icon)
						.priority(5)
						.panel(panel)
						.build();

		clientToolbar.addNavigation(
				navButton
		);
	}

	@Override
	protected void shutDown()
	{
		saveTravelingXp();
		saveBankStandingXp();
		savePrayingXp();
		saveYappingXp();
		saveDoublingDownXp();
		saveExpWasteXp();

		saveDoublingDownState();

		if (travelingTracker != null)
		{
			travelingTracker.reset();
		}

		if (bankStandingTracker != null)
		{
			bankStandingTracker.reset();
		}

		if (prayingTracker != null)
		{
			prayingTracker.reset();
		}

		if (doublingDownTracker != null)
		{
			doublingDownTracker
					.clearTemporaryNpcTracking();
		}

		if (expWasteTracker != null)
		{
			expWasteTracker.reset();
		}

		if (navButton != null)
		{
			clientToolbar.removeNavigation(
					navButton
			);
		}

		panel = null;
		navButton = null;

		travelingTracker = null;
		bankStandingTracker = null;
		prayingTracker = null;
		yappingTracker = null;
		doublingDownTracker = null;
		expWasteTracker = null;
	}

	// =====================================================
	// GAME TICK
	// =====================================================

	@Subscribe
	public void onGameTick(GameTick event)
	{
		/*
		 * IMPORTANT:
		 *
		 * Exp Waste MUST run last.
		 *
		 * That way the other Fake Skills get the
		 * opportunity to tell it that Fake XP was
		 * earned during this tick.
		 */
		updateTraveling();
		updateBankStanding();
		updatePraying();
		updateDoublingDown();

		updateExpWaste();
	}

	// =====================================================
	// TRAVELING
	// =====================================================

	private void updateTraveling()
	{
		if (travelingTracker == null)
		{
			return;
		}

		if (!config.travelingEnabled())
		{
			travelingTracker.reset();
			return;
		}

		double xpEarned =
				travelingTracker.update();

		if (config.ironmanMode()
				&& client.getFollower() != null)
		{
			xpEarned /= 2.0;
		}

		if (xpEarned <= 0.0)
		{
			return;
		}

		traveling.addXp(xpEarned);

		notifyExpWasteOfFakeXp();

		saveTravelingXp();
		updateTravelingDisplay();
	}

	// =====================================================
	// BANK STANDING
	// =====================================================

	private void updateBankStanding()
	{
		if (bankStandingTracker == null)
		{
			return;
		}

		if (!config.bankStandingEnabled())
		{
			bankStandingTracker.reset();
			return;
		}

		double xpEarned =
				bankStandingTracker.update();

		if (xpEarned <= 0.0)
		{
			return;
		}

		bankStanding.addXp(xpEarned);

		notifyExpWasteOfFakeXp();

		saveBankStandingXp();
		updateBankStandingDisplay();
	}

	// =====================================================
	// PRAYING
	// =====================================================

	private void updatePraying()
	{
		if (prayingTracker == null)
		{
			return;
		}

		if (!config.prayingEnabled())
		{
			prayingTracker.reset();
			return;
		}

		double xpEarned =
				prayingTracker.update();

		if (xpEarned <= 0.0)
		{
			return;
		}

		praying.addXp(xpEarned);

		notifyExpWasteOfFakeXp();

		savePrayingXp();
		updatePrayingDisplay();
	}

	// =====================================================
	// DOUBLING DOWN
	// =====================================================

	private void updateDoublingDown()
	{
		if (doublingDownTracker == null)
		{
			return;
		}

		if (!config.doublingDownEnabled())
		{
			doublingDownTracker.clearTemporaryNpcTracking();
			return;
		}

		double xpEarned =
				doublingDownTracker.update();

		saveDoublingDownState();

		if (xpEarned <= 0.0)
		{
			return;
		}

		doublingDown.addXp(
				xpEarned
		);

		notifyExpWasteOfFakeXp();

		saveDoublingDownXp();
		updateDoublingDownDisplay();

	}

	// =====================================================
	// EXP WASTE
	// =====================================================

	private void updateExpWaste()
	{
		if (expWasteTracker == null)
		{
			return;
		}

		if (!config.expWasteEnabled())
		{
			expWasteTracker.reset();
			return;
		}

		double xpEarned =
				expWasteTracker.update();

		if (xpEarned <= 0.0)
		{
			return;
		}

		expWaste.addXp(
				xpEarned
		);

		saveExpWasteXp();
		updateExpWasteDisplay();

	}

	private void notifyExpWasteOfFakeXp()
	{
		if (expWasteTracker != null)
		{
			expWasteTracker
					.notifyFakeXpEarned();
		}
	}

	// =====================================================
	// YAPPING
	// =====================================================

	@Subscribe
	public void onChatMessage(
			ChatMessage event
	)
	{
		if (yappingTracker == null
				|| !config.yappingEnabled())
		{
			return;
		}

		double xpEarned =
				yappingTracker.processMessage(
						event
				);

		if (xpEarned <= 0.0)
		{
			return;
		}

		if (config.ironmanMode())
		{
			xpEarned *= 2.0;
		}

		yapping.addXp(
				xpEarned
		);

		/*
		 * Yapping happens through an event rather
		 * than GameTick, so notify Exp Waste here.
		 */
		notifyExpWasteOfFakeXp();

		saveYappingXp();
		updateYappingDisplay();

	}

	// =====================================================
	// MENU CLICKS
	// =====================================================

	@Subscribe
	public void onMenuOptionClicked(
			MenuOptionClicked event
	)
	{
		if (doublingDownTracker != null
				&& config.doublingDownEnabled())
		{
			doublingDownTracker
					.onMenuOptionClicked(
							event
					);

			saveDoublingDownState();
		}

		if (expWasteTracker != null
				&& config.expWasteEnabled())
		{
			expWasteTracker
					.onMenuOptionClicked(
							event
					);
		}
	}

	// =====================================================
	// COMBAT
	// =====================================================

	@Subscribe
	public void onInteractingChanged(
			InteractingChanged event
	)
	{
		if (doublingDownTracker != null
				&& config.doublingDownEnabled())
		{
			doublingDownTracker
					.onInteractingChanged(
							event
					);
		}
	}

	@Subscribe
	public void onNpcDespawned(
			NpcDespawned event
	)
	{
		if (doublingDownTracker != null
				&& config.doublingDownEnabled())
		{
			doublingDownTracker
					.onNpcDespawned(
							event
					);

			saveDoublingDownState();
		}
	}

	// =====================================================
	// GAME STATE
	// =====================================================

	@Subscribe
	public void onGameStateChanged(
			GameStateChanged event
	)
	{
		if (
				event.getGameState()
						!= GameState.LOGGED_IN
		)
		{
			if (travelingTracker != null)
			{
				travelingTracker.reset();
			}

			if (bankStandingTracker != null)
			{
				bankStandingTracker.reset();
			}

			if (prayingTracker != null)
			{
				prayingTracker.reset();
			}

			if (doublingDownTracker != null)
			{
				saveDoublingDownState();

				doublingDownTracker
						.clearTemporaryNpcTracking();
			}

			if (expWasteTracker != null)
			{
				expWasteTracker.reset();
			}
		}
	}

	// =====================================================
	// DISPLAY
	// =====================================================

	private void updateTravelingDisplay()
	{
		if (panel != null)
		{
			panel.updateTraveling(
					traveling.getLevel(),
					traveling.getXp()
			);
		}
	}

	private void updateBankStandingDisplay()
	{
		if (panel != null)
		{
			panel.updateBankStanding(
					bankStanding.getLevel(),
					bankStanding.getXp()
			);
		}
	}

	private void updatePrayingDisplay()
	{
		if (panel != null)
		{
			panel.updatePraying(
					praying.getLevel(),
					praying.getXp()
			);
		}
	}

	private void updateYappingDisplay()
	{
		if (panel != null)
		{
			panel.updateYapping(
					yapping.getLevel(),
					yapping.getXp()
			);
		}
	}

	private void updateDoublingDownDisplay()
	{
		if (panel != null)
		{
			panel.updateDoublingDown(
					doublingDown.getLevel(),
					doublingDown.getXp()
			);
		}
	}

	private void updateExpWasteDisplay()
	{
		if (panel != null)
		{
			panel.updateExpWaste(
					expWaste.getLevel(),
					expWaste.getXp()
			);
		}
	}

	// =====================================================
	// SAVE XP
	// =====================================================

	private void saveTravelingXp()
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				TRAVELING_XP_KEY,
				traveling.getXp()
		);
	}

	private void saveBankStandingXp()
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				BANK_STANDING_XP_KEY,
				bankStanding.getXp()
		);
	}

	private void savePrayingXp()
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				PRAYING_XP_KEY,
				praying.getXp()
		);
	}

	private void saveYappingXp()
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				YAPPING_XP_KEY,
				yapping.getXp()
		);
	}

	private void saveDoublingDownXp()
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				DOUBLING_DOWN_XP_KEY,
				doublingDown.getXp()
		);
	}

	private void saveExpWasteXp()
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				EXP_WASTE_XP_KEY,
				expWaste.getXp()
		);
	}

	// =====================================================
	// SAVE DOUBLING DOWN STATE
	// =====================================================

	private void saveDoublingDownState()
	{
		if (doublingDownTracker == null)
		{
			return;
		}

		String monsterName =
				doublingDownTracker
						.getWaitingMonsterName();

		if (monsterName == null)
		{
			configManager.unsetConfiguration(
					CONFIG_GROUP,
					DOUBLING_DOWN_MONSTER_KEY
			);
		}
		else
		{
			configManager.setConfiguration(
					CONFIG_GROUP,
					DOUBLING_DOWN_MONSTER_KEY,
					monsterName
			);
		}

		String action =
				doublingDownTracker
						.getWaitingAction();

		if (action == null)
		{
			configManager.unsetConfiguration(
					CONFIG_GROUP,
					DOUBLING_DOWN_ACTION_KEY
			);
		}
		else
		{
			configManager.setConfiguration(
					CONFIG_GROUP,
					DOUBLING_DOWN_ACTION_KEY,
					action
			);
		}

		configManager.setConfiguration(
				CONFIG_GROUP,
				DOUBLING_DOWN_REWARD_KEY,
				doublingDownTracker
						.isDoubleRewardNext()
		);
	}

	// =====================================================
	// LOAD XP
	// =====================================================

	private void loadTravelingXp()
	{
		loadXp(
				traveling,
				configManager.getConfiguration(
						CONFIG_GROUP,
						TRAVELING_XP_KEY
				)
		);
	}

	private void loadBankStandingXp()
	{
		loadXp(
				bankStanding,
				configManager.getConfiguration(
						CONFIG_GROUP,
						BANK_STANDING_XP_KEY
				)
		);
	}

	private void loadPrayingXp()
	{
		loadXp(
				praying,
				configManager.getConfiguration(
						CONFIG_GROUP,
						PRAYING_XP_KEY
				)
		);
	}

	private void loadYappingXp()
	{
		loadXp(
				yapping,
				configManager.getConfiguration(
						CONFIG_GROUP,
						YAPPING_XP_KEY
				)
		);
	}

	private void loadDoublingDownXp()
	{
		loadXp(
				doublingDown,
				configManager.getConfiguration(
						CONFIG_GROUP,
						DOUBLING_DOWN_XP_KEY
				)
		);
	}

	private void loadExpWasteXp()
	{
		loadXp(
				expWaste,
				configManager.getConfiguration(
						CONFIG_GROUP,
						EXP_WASTE_XP_KEY
				)
		);
	}

	// =====================================================
	// LOAD DOUBLING DOWN STATE
	// =====================================================

	private void loadDoublingDownState()
	{
		if (doublingDownTracker == null)
		{
			return;
		}

		String monsterName =
				configManager.getConfiguration(
						CONFIG_GROUP,
						DOUBLING_DOWN_MONSTER_KEY
				);

		doublingDownTracker
				.setWaitingMonsterName(
						monsterName
				);

		String action =
				configManager.getConfiguration(
						CONFIG_GROUP,
						DOUBLING_DOWN_ACTION_KEY
				);

		doublingDownTracker
				.setWaitingAction(
						action
				);

		String rewardState =
				configManager.getConfiguration(
						CONFIG_GROUP,
						DOUBLING_DOWN_REWARD_KEY
				);

		doublingDownTracker
				.setDoubleRewardNext(
						Boolean.parseBoolean(
								rewardState
						)
				);
	}

	// =====================================================
	// SHARED XP LOADER
	// =====================================================

	private void loadXp(
			FakeSkillData skill,
			String savedXp
	)
	{
		if (savedXp == null)
		{
			skill.setXp(0.0);
			return;
		}

		try
		{
			skill.setXp(
					Double.parseDouble(
							savedXp
					)
			);
		}
		catch (NumberFormatException ignored)
		{
			skill.setXp(0.0);
		}
	}

	@Provides
	FakeSkillsConfig provideConfig(
			ConfigManager configManager
	)
	{
		return configManager.getConfig(
				FakeSkillsConfig.class
		);
	}
}

package com.fakeskills;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;

public class PrayingTracker
{
    /*
     * Base XP for each Prayer point lost,
     * multiplied by the number of prayers
     * currently active.
     */
    private static final double XP_PER_PRAYER_POINT = 4.5;

    /*
     * Maximum number of simultaneously
     * active prayers that can multiply XP.
     */
    private static final int MAX_ACTIVE_PRAYERS = 15;

    /*
     * Prayer-point losses larger than this
     * are rejected completely.
     */
    private static final int MAX_QUALIFYING_DRAIN = 15;

    private final Client client;

    /*
     * -1 means we haven't recorded the
     * player's Prayer points yet.
     */
    private int previousPrayerPoints = -1;

    public PrayingTracker(Client client)
    {
        this.client = client;
    }

    /*
     * Called once per GameTick.
     */
    public double update()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            reset();
            return 0.0;
        }

        int currentPrayerPoints =
                client.getBoostedSkillLevel(
                        Skill.PRAYER
                );

        /*
         * First observation.
         *
         * Establish the starting value
         * without awarding XP.
         */
        if (previousPrayerPoints < 0)
        {
            previousPrayerPoints =
                    currentPrayerPoints;

            return 0.0;
        }

        int prayerPointsLost =
                previousPrayerPoints
                        - currentPrayerPoints;

        /*
         * Remember the current value for
         * our next GameTick.
         */
        previousPrayerPoints =
                currentPrayerPoints;

        /*
         * No Prayer points were consumed.
         *
         * This also prevents Prayer restores,
         * altars, potions, etc. from
         * awarding XP.
         */
        if (prayerPointsLost <= 0)
        {
            return 0.0;
        }

        /*
         * Reject unusually large Prayer
         * losses.
         */
        if (
                prayerPointsLost
                        > MAX_QUALIFYING_DRAIN
        )
        {
            return 0.0;
        }

        /*
         * Count how many prayers are
         * currently active.
         */
        int activePrayers =
                countActivePrayers();

        /*
         * Prayer points disappeared but
         * no prayers are active.
         *
         * Do not award Fake Praying XP.
         */
        if (activePrayers <= 0)
        {
            return 0.0;
        }

        /*
         * Cap the multiplier at 15 active
         * prayers.
         */
        if (activePrayers > MAX_ACTIVE_PRAYERS)
        {
            activePrayers =
                    MAX_ACTIVE_PRAYERS;
        }

        /*
         * FINAL FORMULA:
         *
         * Prayer points lost
         * ×
         * active prayers
         * ×
         * 4.5 XP
         *
         * Examples:
         *
         * 1 point × 1 prayer × 4.5
         * = 4.5 XP
         *
         * 1 point × 3 prayers × 4.5
         * = 13.5 XP
         *
         * 2 points × 3 prayers × 4.5
         * = 27 XP
         *
         * 1 point × 10 prayers × 4.5
         * = 45 XP
         */
        return prayerPointsLost
                * activePrayers
                * XP_PER_PRAYER_POINT;
    }

    /*
     * Count every prayer RuneLite reports
     * as currently active.
     */
    @SuppressWarnings("deprecation")
    private int countActivePrayers()
    {
        int count = 0;

        for (Prayer prayer : Prayer.values())
        {
            if (client.isPrayerActive(prayer))
            {
                count++;
            }
        }

        return count;
    }

    public void reset()
    {
        previousPrayerPoints = -1;
    }
}

package com.fakeskills;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

public class TravelingTracker
{
    /*
     * Traveling XP:
     *
     * Normal:
     * 1.5 XP per tile
     *
     * With follower:
     * 3.0 XP per tile
     */
    private static final double XP_PER_TILE = 1.5;

    /*
     * Walking = normally 1 tile between ticks.
     * Running = normally up to 2.
     *
     * Anything larger is rejected so teleports
     * don't become Traveling XP.
     */
    private static final int MAX_NORMAL_MOVEMENT = 2;

    private final Client client;

    private WorldPoint previousLocation;

    public TravelingTracker(Client client)
    {
        this.client = client;
    }

    public double update()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            reset();
            return 0.0;
        }

        Player player =
                client.getLocalPlayer();

        if (player == null)
        {
            reset();
            return 0.0;
        }

        WorldPoint currentLocation =
                player.getWorldLocation();

        /*
         * First observation.
         */
        if (previousLocation == null)
        {
            previousLocation =
                    currentLocation;

            return 0.0;
        }

        /*
         * Plane changed.
         *
         * Don't count this as normal
         * Traveling movement.
         */
        if (
                currentLocation.getPlane()
                        != previousLocation.getPlane()
        )
        {
            previousLocation =
                    currentLocation;

            return 0.0;
        }

        int distance =
                previousLocation.distanceTo(
                        currentLocation
                );

        /*
         * Remember our new position.
         */
        previousLocation =
                currentLocation;

        /*
         * Didn't move.
         */
        if (distance <= 0)
        {
            return 0.0;
        }

        /*
         * Too large to consider ordinary
         * walking/running.
         */
        if (distance > MAX_NORMAL_MOVEMENT)
        {
            return 0.0;
        }

        double multiplier = 1.0;

        /*
         * Your follower/pet doubles
         * Traveling XP.
         */
        if (client.getFollower() != null)
        {
            multiplier = 2.0;
        }

        return distance
                * XP_PER_TILE
                * multiplier;
    }

    public void reset()
    {
        previousLocation = null;
    }
}

package com.fakeskills;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

public class YappingTracker
{
    private static final double XP_PER_CHARACTER = 1.0;

    private final Client client;

    public YappingTracker(Client client)
    {
        this.client = client;
    }

    public double processMessage(ChatMessage event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return 0.0;
        }

        if (event == null)
        {
            return 0.0;
        }

        ChatMessageType type =
                event.getType();

        if (!isPlayerChatType(type))
        {
            return 0.0;
        }

        /*
         * PRIVATECHATOUT is specifically an
         * outgoing private message, so we
         * already know it belongs to us.
         */
        if (type != ChatMessageType.PRIVATECHATOUT)
        {
            if (!isOurMessage(event))
            {
                return 0.0;
            }
        }

        String message =
                event.getMessage();

        if (message == null)
        {
            return 0.0;
        }

        /*
         * Remove RuneLite/Jagex formatting
         * tags before counting characters.
         *
         * Spaces and punctuation remain.
         */
        String cleanMessage =
                Text.removeTags(message);

        if (cleanMessage == null
                || cleanMessage.isEmpty())
        {
            return 0.0;
        }

        /*
         * Count Unicode characters rather
         * than raw Java storage units.
         *
         * This means normal letters,
         * numbers, punctuation, spaces,
         * and most emoji count naturally.
         */
        int characterCount =
                cleanMessage.codePointCount(
                        0,
                        cleanMessage.length()
                );

        return characterCount
                * XP_PER_CHARACTER;
    }

    private boolean isPlayerChatType(
            ChatMessageType type
    )
    {
        switch (type)
        {
            case PUBLICCHAT:
            case MODCHAT:
            case PRIVATECHATOUT:
            case FRIENDSCHAT:
            case CLAN_CHAT:
            case CLAN_GUEST_CHAT:
            case CLAN_GIM_CHAT:
                return true;

            default:
                return false;
        }
    }

    private boolean isOurMessage(
            ChatMessage event
    )
    {
        Player player =
                client.getLocalPlayer();

        if (player == null
                || player.getName() == null)
        {
            return false;
        }

        String eventName =
                event.getName();

        if (eventName == null)
        {
            return false;
        }

        String ourName =
                normalizeName(
                        player.getName()
                );

        String messageName =
                normalizeName(
                        eventName
                );

        return ourName.equalsIgnoreCase(
                messageName
        );
    }

    private String normalizeName(
            String name
    )
    {
        return Text.removeTags(name)
                .replace('\u00A0', ' ')
                .trim();
    }
}

